                    if (!was.equals(request.today())) {
                        rollups.snapshot(sheet, by);
                    }
                    Sheet changed = service.setToday(sheet, request.today());
                    if (!was.equals(changed.getToday())) {
                        claims.releaseLocks(sheet);
                    }
